    "complete": true,
    "content": "**区域：**综合功能/髋膝踝/步态　 **等级：**L1基础；有规定辅助条件的个体化步行观察\n\n**目标：**观察家庭中自然起步、连续迈步、停步和必要转身的功能表现、辅助需求与症状；无标准4 m路径或无尺度时仍可使用，但不报告标准步速或m/s。\n\n**器材**\n\n- 平整、清理杂物且不打滑的一小段通路\n- 日常合适鞋及平时使用的助行器（如需要）\n- 手机固定支架；按当前情况安排可协助的陪同者\n\n**开始条件**\n\n- 当前允许相应程度的承重，能在既定辅助条件下安全起步；新近外伤承重资格不明时先澄清，不让用户靠试走排除骨折。\n- 有近期反复跌倒、明显站立不稳或既定陪同要求者，不安排独自测试。场地或个人条件不允许安全迈步时使用已有日常活动报告，不强行录像。\n\n**准备与起始位：**选择家中能自然走几步的实际通路，记录长度是否实测、鞋、助行器、扶持和地面条件；不要求凑够4 m。相机固定，尽量包含全身、双脚和通路。无需为观察功能强行完成尺度标定。\n\n**操作步骤**\n\n1. 先在起点站稳，报告此刻症状和所用辅助；陪同者站在方便协助而不挡路的位置。\n2. 按平时舒适速度沿通路自然迈步，不为镜头刻意加快或放慢，也不边走边拿手机。\n3. 走到预定安全位置后停稳；空间足够且当前允许时，可舒适转身再返回，否则本次只观察单向步行。\n4. 结束后记录是否需要临时扶墙、有人扶持、停顿或发生熟悉症状；选择仍有决策价值时才增加一次观察。\n\n**关键要领**\n\n- 用你平时的步伐，先顾好走路，不用追求步数或速度成绩。\n- 平时需要的助行器照常使用，不为展示能力撤掉。\n- 转身空间不够就停稳，不挤着转或绕开危险家具。\n- 感觉需要停下来或扶稳时立即照做，并说明原因。\n\n**常见错误**\n\n- 把无尺度的像素位移除以时间，直接显示为m/s或4 m步行测试分数。\n- 短通路中多次起停与转身被当作稳态直线步行，与其他测试协议直接比较。\n- 为拍清全身要求用户走入狭窄区域、撤掉助行器，或让陪同者后退拍摄而无法协助。\n\n**试做与候选剂量／评估协议：**本库功能观察方案：通常1趟足够；若第一趟已获可用信息不重复。必要时再观察1趟，两趟之间坐下或扶稳休息30–60秒或更久，直到回到舒适状态。实际长度、次数与休息为任务条件，不是标准4 m步速协议。\n\n**退阶：**缩短为安全范围内的少量自然步行，增加已允许的助行/陪同；若仍不适合，保存用户日常走路、转移困难及辅助需求的报告，或改为另注册的坐站观察。改变辅助或任务后另记协议，不冒充同条件步行通过。\n\n**进阶：**同条件复测可观察个人变化；确有步速评估需求时另启用有实测距离、固定计时边界和适用验证的标准步行协议。需要更复杂转向时另选注册任务，不在本卡直接增加负重或快走。\n\n**停止或调整条件**\n\n- 出现明显失衡、腿软、新发锐痛或当前症状明显恶化时停止并扶稳/坐下。\n- 出现胸痛、晕厥或不能用一般用力解释的明显不适时终止测试并按系统分流。\n\n**机位与画面：**优先固定的侧前方或侧面全身视角，视野覆盖实际安全通路；不能同时看清全程时保留可见段，不强迫用户重新摆机位反复走。\n\n**视觉可以观察**\n\n- 可见段中的起步、连续迈步、明显停顿、停步和转身过程。\n- 清楚可见时的步数、节律、明显左右动作差异与临时扶持事件；接触边界不清时对应指标标未知。\n- 用户自报的症状和困难另存自述证据，不由步态外观自动生成疼痛评分。\n\n**视觉不能直接判定**\n\n- 没有实测距离或可靠地面尺度时不能输出m/s、真实步长或标准4 m步行结果。\n- 有限单目短片不能直接确定关节接触力、地面反力、肌力等级或步态异常的病因。\n- 看不见的路段、跌倒风险全貌及助行器实际承担的力，不能由模型补造。\n\n**观察不足时：**没有4 m空间、没有尺度或局部出画时仍保留本次功能观察及自述；速度字段置未知，不让用户为得到m/s反复重拍。已有录像可重分析。安全性本身不满足时停止行走任务，改用允许的替代而不是仅降级测量。\n\n**动作出处与对应原文：**[REF-S079]；Walking for health：自然步行；本卡为短距离功能观察。\n\n**证据性质与适用范围：**公共卫生机构活动说明。运动形式有公开出处；本卡为项目功能观察，不能解释为已验证标准量表或诊断测试。\n\n**依据：**[REF-S079]；背景及临床边界：[GEN-S03]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[GEN-S05]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
