    "sourceDose": "本库候选观察协议：每侧先1次近距离熟悉，再按3个方向各做1次；只有需要判断重复性且仍舒适时才每方向加1次。方向间可把两脚落地休息，侧间至少30–60秒或至稳定舒适。剂量属于设计方案，不是标准Y-Balance/SEBT施测次数。\n\n见习34仅记录Y-Balance前向触及且尝试数不一致、无腿长，不输出标准化/综合分数。见习28的“单腿下蹲伸膝距离”缺正式协议及单位，不擅自视为Y-Balance。原始数据只作为当次记录；本卡仍是非标准化触点任务。",
