    "region": "综合下肢、步态",
    "level": "L1基础",
    "equipment": "4米实测通道、起终点贴条、平整地面；允许原有助行器",
    "objective": "记录固定路径常速行走能力。",
    "startConditions": "能安全通过通道，无需相机跟随而制造绊倒风险。 按当前伤情、负重许可和手术限制选择；既往力量强不能绕过急伤保护。",
