    "level": "L0低负荷支持—L1基础",
    "equipment": "固定台面或稳固椅背",
    "objective": "观察向后抬腿能力及腰骨盆共同代偿。",
    "startConditions": "站立和平衡足够，无被禁止的髋后伸方向。 按当前伤情、负重许可和手术限制选择；既往力量强不能绕过急伤保护。",
    "stopConditions": "出现前髋明显牵痛、腰部新锐痛、麻木或站立不稳时结束。",
