    "id": "E-LOW-003",
    "name": "扶稳髋外展与小幅内收",
    "kind": "assessment",
    "complete": true,
    "content": "**区域：**髋　 **等级：**L0低负荷支持—L1基础\n\n**目标：**观察侧向移动范围、侧差及控制能力。\n\n**器材：**稳固扶手\n\n**开始条件：**允许站立负重，且髋内收未被术后限制。 按当前伤情、负重许可和手术限制选择；既往力量强不能绕过急伤保护。\n\n**准备与起始位：**正面机位；支撑腿站稳，测试腿前后均有空间。\n\n**操作步骤**\n\n1. 从自然站姿缓慢把一侧腿移向外侧。\n2. 达到舒适终点后回到起点。\n3. 若允许内收，再让测试腿轻轻向中线靠近或小幅越过中线。\n4. 另一侧以相同扶手和幅度规则重复。\n\n**关键要领**\n\n- 足尖尽量维持自然向前。\n- 身体不要向相反方向甩动。\n- 外展与内收分别记录，不合成一个角。\n\n**常见错误**\n\n- 抬高骨盆来制造外展幅度。\n- 交叉腿过远引起站立失衡。\n\n**试做与候选剂量／评估协议：**候选协议：每侧每方向1次熟悉、2次记录；内收受限者只做外展，缺项不是失败。\n\n**退阶：**坐位小幅滑动腿，或只完成许可方向。\n\n**进阶：**需要精准髋角时补骨盆定位和专门测量。\n\n**停止或调整条件：**明显腹股沟疼痛、术区牵拉、交叉腿不稳或禁忌方向出现时停止。\n\n**机位与画面：**正面全身，双髋和双膝可见。\n\n**视觉可以观察：**二维大腿侧向运动、躯干侧倾、次数。\n\n**视觉不能直接判定：**真实骨盆定位、深层组织牵拉、独立内收肌力。\n\n**观察不足时：**保留已完成方向；其他方向记未测，不要求补齐才出结果。\n\n**动作出处与对应原文：**[REF-S001]；Leg extension（站姿后伸）、Sideways leg lift（外展及回收）。\n\n**证据性质与适用范围：**公共卫生机构动作说明。运动形式有公开出处；本卡为项目功能观察，不能解释为已验证标准量表或诊断测试。\n\n**依据：**[REF-S001]；背景及临床边界：[LOW-S08] [LOW-S21]。动作形式、背景指南和产品测量证据按第8节分别解释。",
