    "objective": "观察侧向移动范围、侧差及控制能力。",
    "startConditions": "允许站立负重，且髋内收未被术后限制。 按当前伤情、负重许可和手术限制选择；既往力量强不能绕过急伤保护。",
    "stopConditions": "明显腹股沟疼痛、术区牵拉、交叉腿不稳或禁忌方向出现时停止。",
    "sourceDose": "候选协议：每侧每方向1次熟悉、2次记录；内收受限者只做外展，缺项不是失败。",
