    "equipment": "足够高的稳固椅、可选大腿位置标记",
    "objective": "观察旋转活动表现与左右差异。",
    "startConditions": "能稳定坐位；髋旋转没有术后或急伤方向限制。 按当前伤情、负重许可和手术限制选择；既往力量强不能绕过急伤保护。",
    "stopConditions": "腹股沟卡住、明显疼痛、术区不适或动作不稳即停止。",
    "sourceDose": "候选协议：每方向2次缓慢主动运动，必要时先熟悉1次；记录椅高和膝姿势，条件不同不直接比角度。",
