    "id": "E-AXU-019",
    "name": "腕主动掌屈/背伸ROM筛查",
    "kind": "assessment",
    "complete": true,
    "content": "**区域：**腕　 **等级：**L0–L1\n\n**目标：**测统一成像平面中的手相对前臂投影活动。\n\n**器材**\n\n- 桌面\n\n**开始条件**\n\n- 腕活动在当前限制内；无未评估的急性创伤或明显肿胀。\n\n**准备与起始位：**前臂放稳在桌面，手腕伸出桌边，手保持轻松张开；手机拍腕的侧面近景并包含肘。\n\n**操作步骤**\n\n1. 前臂稳定，从手与前臂自然相接的中立位开始。\n2. 缓慢掌屈，让手向掌侧落下，再回中立。\n3. 缓慢背伸，让手向手背方向抬起，再回中立。\n4. 分别记录症状和可见范围，手指不需参加测试。\n\n**关键要领**\n\n- 前臂不要离开桌面。\n- 手指保持轻松，避免用大幅屈指改变手部方向。\n- 只主动移动，不用另一手掰腕。\n\n**常见错误**\n\n- 整条前臂抬起制造腕角。\n- 仅用肘与腕两个点计算手腕屈伸。\n\n**试做与候选剂量／评估协议：**每方向1–2次，间隔10–15秒；保存前臂姿势、镜头和是否有支撑。\n\n**退阶：**缩小范围或仅记录可完成的方向。\n\n**进阶：**同支撑与机位复测；负荷能力需另外测试。\n\n**停止或调整条件**\n\n- 局部锐痛、明显卡住或新手麻。\n- 腕肿痛显著增加或无法控制回到中立。\n\n**机位与画面：**腕侧面近景；使用统一图像坐标的前臂轴和掌部轴。\n\n**视觉可以观察**\n\n- 规定视角的腕投影屈伸范围与次数。\n- 前臂是否明显抬离支撑。\n\n**视觉不能直接判定**\n\n- 腕骨间运动、韧带稳定性或握力。\n- 独立Hand与Body world未经配准的公制关节角。\n\n**观察不足时：**手边缘导致Hand失跟时保留主诉及已见范围；可陪同完成而不打分。\n\n**动作出处与对应原文：**[REF-S016]；主动旋前/旋后、腕掌屈/背伸、桡偏/尺偏。\n\n**证据性质与适用范围：**大学医院动作说明。运动形式有公开出处；本卡为项目功能观察，不能解释为已验证标准量表或诊断测试。\n\n**依据：**[REF-S016]；背景及临床边界：[AXU-S11] [AXU-S08]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
    "version": "2026-10-13-full",
