    "startConditions": "- 腕活动在当前限制内；无未评估的急性创伤或明显肿胀。",
    "stopConditions": "- 局部锐痛、明显卡住或新手麻。\n- 腕肿痛显著增加或无法控制回到中立。",
    "sourceDose": "每方向1–2次，间隔10–15秒；保存前臂姿势、镜头和是否有支撑。",
