    "level": "L1基础",
    "equipment": "垫、小枕头、可选膝上弹力带",
    "objective": "练习屈髋位旋转/外展控制，作为候选辅助训练。",
    "startConditions": "侧卧可耐受，髋旋转在许可范围。 外加负荷须可控，场地和支撑可靠；本动作不是最大负荷测试，不做到无法受控回程。 按当前伤情、负重许可和手术限制选择；既往力量强不能绕过急伤保护。",
    "stopConditions": "髋前夹痛、外侧压痛或腰部新不适时停。",
