    "startConditions": "已掌握徒手髋铰链，能安全提放器械；当前允许后侧链负荷。 外加负荷须可控，场地和支撑可靠；本动作不是最大负荷测试，不做到无法受控回程。 按当前伤情、负重许可和手术限制选择；既往力量强不能绕过急伤保护。",
    "stopConditions": "锐痛、向腿放射、握持松脱或回程明显失控时结束。",
