    "startConditions": "允许双脚负重，明确深度和扶手方案。 按当前伤情、负重许可和手术限制选择；既往力量强不能绕过急伤保护。",
    "stopConditions": "新锐痛、卡锁、腿软、踝失稳或持续症状升级时停。",
    "sourceDose": "候选模板：首轮3次小幅；一般1—3组×5—12次，以可控动作及近期症状决定幅度与总量。",
