    "id": "T-AXU-004",
    "name": "仰卧屈膝小幅左右摆膝",
    "kind": "training",
    "complete": true,
    "content": "**区域：**腰部/胸腰与骨盆整体　 **等级：**L0\n\n**目标：**在支撑位练习舒适的躯干旋转活动。\n\n**器材**\n\n- 垫或稳定床面\n\n**开始条件**\n\n- 能安全仰卧，当前允许屈膝和小幅旋转；不要求术后限制者扭转。\n\n**准备与起始位：**仰卧屈膝，双脚踩稳并靠近，双手自然打开，肩背放松。\n\n**操作步骤**\n\n1. 保持双膝大致并拢，呼吸恢复平稳。\n2. 让双膝缓慢向一侧倾斜一小段，脚可随之自然滚动。\n3. 控制双膝回到中间，再向另一侧。\n4. 若一侧不适，缩小该侧范围并记录，不强行压到床面。\n\n**关键要领**\n\n- 肩部自然接触床面，不用手把膝拉下去。\n- 脚跟不猛蹬，速度保持均匀。\n- 动作是整体活动，不追求腰部某节发响。\n\n**常见错误**\n\n- 把膝压到底或利用惯性扭动。\n- 把摆膝的可见角度称为腰椎真实旋转角。\n\n**试做与候选剂量／评估协议：**首轮每侧3次；候选模板1–2组×每侧5–8次，组间30秒；由计划决定是否使用。\n\n**退阶：**减少倾斜幅度，在膝下加支撑限制范围。\n\n**进阶：**增加可控舒适范围；抗旋转负重能力另用Pallof，不靠更猛摆膝获得。\n\n**停止或调整条件**\n\n- 新的下肢放射痛、麻木或腰部锐痛。\n- 症状在回到中间后仍持续加重。\n\n**机位与画面：**斜上方或床侧全身；注意不因床沿遮挡强求测角。\n\n**视觉可以观察**\n\n- 双膝左右移动、回中间、节奏和完成次数。\n\n**视觉不能直接判定**\n\n- 腰椎分节旋转、骶髂复位或椎间受力。\n\n**观察不足时：**可按节奏陪练并询问感觉；不计算无法区分的局部旋转角。\n\n**动作出处与对应原文：**[REF-S075]；Knee rolls：仰卧屈膝左右摆膝。\n\n**证据性质与适用范围：**医院动作说明。运动形式有公开出处；本卡的减负荷、扶持、候选剂量及视频规则属于实施版本，不能据此声明完整方案已验证疗效。\n\n**依据：**[REF-S075]；背景及临床边界：[AXU-S01]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
