    "content": "**区域：**颈部　 **等级：**L0\n\n**目标：**恢复可耐受的低头活动与动作控制。\n\n**器材**\n\n- 稳定椅\n\n**开始条件**\n\n- 当前低头方向获准，无需先处理的近期创伤或新神经症状。\n\n**准备与起始位：**坐稳，肩自然放松，眼睛平视，手机侧面近景。\n\n**操作步骤**\n\n1. 从自然中立位开始。\n2. 缓慢让下巴朝胸前方向移动，到舒适位置即止。\n3. 停短暂后平稳回到原视线高度。\n4. 每次回正后确认没有新的头晕或手臂症状。\n\n**关键要领**\n\n- 不把下巴硬压到胸口。\n- 肩和胸口尽量不跟着大幅前弯。\n- 不靠手压头，保持呼吸。\n\n**常见错误**\n\n- 快速点头或手压到末端。\n- 为达到统一目标角度继续疼痛活动。\n\n**试做与候选剂量／评估协议：**首轮3次；候选模板1–2组×5–8次，组间30秒，角度和频次由个体计划确认。\n\n**退阶：**更小幅度，靠背支撑；必要时只做轻点头控制。\n\n**进阶：**逐渐扩大可耐受范围和生活低头时间，不先增加外载。\n\n**停止或调整条件**\n\n- 眩晕、视物异常或新麻木无力。\n- 异常头颈痛或症状持续增高。\n\n**机位与画面：**侧面头肩近景；Face有效时估计相对俯仰趋势。\n\n**视觉可以观察**\n\n- 低头与回正、近似范围、明显躯干前弯。\n\n**视觉不能直接判定**\n\n- 分节颈椎运动和神经状态。\n\n**观察不足时：**以节奏与主诉完成，Face缺失不强制重复低头。\n\n**动作出处与对应原文：**[REF-S012]；Neck flexion / Side flexion / Rotation / Chin retraction。\n\n**证据性质与适用范围：**大学医院动作说明。运动形式有公开出处；本卡的减负荷、扶持、候选剂量及视频规则属于实施版本，不能据此声明完整方案已验证疗效。\n\n**依据：**[REF-S012]；背景及临床边界：[AXU-S02] [AXU-S10]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
