    "content": "**区域：**颈部　 **等级：**L0\n\n**目标：**恢复当前允许的抬头活动，不作颈椎加压。\n\n**器材**\n\n- 稳定椅\n\n**开始条件**\n\n- 抬头方向试做可耐受，近期创伤或新神经症状已先处理。\n\n**准备与起始位：**坐稳，胸口自然朝前，双肩放松；不把椅背顶在颈后。\n\n**操作步骤**\n\n1. 自然平视，先放松呼吸。\n2. 缓慢抬高视线，让头部小幅后仰至舒适位置。\n3. 平稳回到平视，不停留追求极限。\n4. 检查有无头晕、视觉或上肢变化后再继续。\n\n**关键要领**\n\n- 只做舒适范围，不能用手把额头往后推。\n- 胸腰不要同时明显后仰。\n- 回正过程和抬起一样缓慢。\n\n**常见错误**\n\n- 仰到极限并长时间保持。\n- 把不适解释成必须拉开的僵硬而继续增加幅度。\n\n**试做与候选剂量／评估协议：**首轮2–3次；候选模板1–2组×5次，组间30秒；需由当前方向选择确认。\n\n**退阶：**缩小范围或暂时只练回到中立位。\n\n**进阶：**逐步恢复日常抬头需求；不加入颈部负重或加压。\n\n**停止或调整条件**\n\n- 眩晕、恶心、视物异常或新的放射症状。\n- 异常剧烈头颈痛。\n\n**机位与画面：**侧面头肩近景，Face记录近似俯仰。\n\n**视觉可以观察**\n\n- 抬头回正、明显胸腰随动和可见节奏。\n\n**视觉不能直接判定**\n\n- 颈椎血管状态、分节负荷或神经孔变化。\n\n**观察不足时：**角度失跟时停用评分，用户可完成获准小范围或跳过。\n\n**动作出处与对应原文：**[REF-S013]；第2页 Neck extension / Isometric neck flexion, lateral flexion, rotation。\n\n**证据性质与适用范围：**医院动作说明。运动形式有公开出处；本卡的减负荷、扶持、候选剂量及视频规则属于实施版本，不能据此声明完整方案已验证疗效。\n\n**依据：**[REF-S013]；背景及临床边界：[AXU-S02] [AXU-S10]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
