    "content": "**区域：**颈部　 **等级：**L0\n\n**目标：**练习舒适的侧向活动与抬肩控制。\n\n**器材**\n\n- 稳定椅\n\n**开始条件**\n\n- 主动侧屈可耐受；无需先处理的创伤或新神经症状。\n\n**准备与起始位：**正面坐稳，眼睛平视，双肩自然下垂。\n\n**操作步骤**\n\n1. 缓慢让一侧耳朵靠近同侧肩的方向。\n2. 在舒适位置停短暂，肩不迎向耳朵。\n3. 回中立位，再换另一侧。\n4. 每轮后报告是否只是轻牵拉，或出现熟悉/新的症状。\n\n**关键要领**\n\n- 鼻尖尽量朝前，避免边转头边侧屈。\n- 不使用手拉头。\n- 侧屈和回正都缓慢，呼吸不中断。\n\n**常见错误**\n\n- 耸肩换取更短耳肩距离。\n- 把拉得越痛当作越有效。\n\n**试做与候选剂量／评估协议：**首轮每侧3次；候选模板1–2组×每侧5次，组间30秒；范围由计划决定。\n\n**退阶：**缩小范围，靠背坐稳。\n\n**进阶：**增加可耐受活动或短暂控制，不加手压。\n\n**停止或调整条件**\n\n- 眩晕、异常头痛或新手麻无力。\n- 局部锐痛或回正后仍持续加重。\n\n**机位与画面：**正面头肩近景。\n\n**视觉可以观察**\n\n- 近似头部侧倾、肩线变化和次数。\n\n**视觉不能直接判定**\n\n- 局部颈肌长度、神经压迫与真实节段ROM。\n\n**观察不足时：**只做节奏指导及症状收集，不让头姿丢失触发重做。\n\n**动作出处与对应原文：**[REF-S012]；Neck flexion / Side flexion / Rotation / Chin retraction。\n\n**证据性质与适用范围：**大学医院动作说明。运动形式有公开出处；本卡的减负荷、扶持、候选剂量及视频规则属于实施版本，不能据此声明完整方案已验证疗效。\n\n**依据：**[REF-S012]；背景及临床边界：[AXU-S02] [AXU-S10]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
