    "content": "**区域：**颈部　 **等级：**L0\n\n**目标：**恢复日常观察两侧所需的转头能力。\n\n**器材**\n\n- 稳定椅\n\n**开始条件**\n\n- 转头方向可耐受；创伤或新神经症状已先评估。\n\n**准备与起始位：**胸口朝前坐稳，双脚落地，手机正面头肩近景。\n\n**操作步骤**\n\n1. 从自然平视位开始，缓慢向一侧转头。\n2. 到舒适范围即控制回正，不需眼睛看向身后。\n3. 回正后再转另一侧。\n4. 完成少量次数后询问头晕及颈肩臂症状。\n\n**关键要领**\n\n- 下巴高度自然，不先仰头。\n- 身体尽量朝前，不用扭胸补角度。\n- 两次之间先回稳中立位。\n\n**常见错误**\n\n- 快甩头或反复冲末端。\n- 为了让相机继续看到脸而改变整个动作姿势。\n\n**试做与候选剂量／评估协议：**首轮每侧3次；候选模板1–2组×每侧5–8次，组间30秒；由计划限定范围。\n\n**退阶：**减小范围，靠背支撑。\n\n**进阶：**逐渐恢复生活所需范围，之后再结合安全环境中的视线转移任务。\n\n**停止或调整条件**\n\n- 眩晕、恶心、视觉异常或新上肢症状。\n- 异常突发头颈痛。\n\n**机位与画面：**正面头肩近景，保留Face置信度与可见范围。\n\n**视觉可以观察**\n\n- 转头方向、回正、近似范围与躯干明显随动。\n\n**视觉不能直接判定**\n\n- 全程精确颈旋转、血管和神经情况。\n\n**观察不足时：**看不到侧脸末端也可保留练习时长和自报次数，不补算末端。\n\n**动作出处与对应原文：**[REF-S012]；Neck flexion / Side flexion / Rotation / Chin retraction。\n\n**证据性质与适用范围：**大学医院动作说明。运动形式有公开出处；本卡的减负荷、扶持、候选剂量及视频规则属于实施版本，不能据此声明完整方案已验证疗效。\n\n**依据：**[REF-S012]；背景及临床边界：[AXU-S02] [AXU-S10]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
