    "content": "**区域：**颈部　 **等级：**L1\n\n**目标：**在头部大致不动时练习可耐受的颈部用力与耐力。\n\n**器材**\n\n- 自己的手掌；无需弹力带\n\n**开始条件**\n\n- 颈部等长已获当前计划允许，无急性未评估创伤。\n- 用户理解只需轻抵，不是最大用力测试。\n\n**准备与起始位：**坐稳，头中立；选择额头或头侧一个获准方向，手掌轻贴。\n\n**操作步骤**\n\n1. 先放松呼吸，建立很轻的手头接触。\n2. 逐渐轻抵手掌，让头保持大致原位而不是明显推动。\n3. 保持短暂、持续呼吸，然后逐渐卸力。\n4. 充分放松后再重复；换方向前重新确认症状。\n\n**关键要领**\n\n- 力量慢慢上来、慢慢下去。\n- 手和头互相轻抵，不用全力比赛。\n- 牙关和肩部尽量放松，避免屏气。\n\n**常见错误**\n\n- 突然发力或用手把头扳向末端。\n- 机器计时完成就认为真实用力已被检测。\n\n**试做与候选剂量／评估协议：**首轮每个选定方向2次×3秒；候选模板每方向3–5次×5秒、次间休息10–20秒；方向与力度由计划确认。\n\n**退阶：**减小自报用力或只保持自然头位。\n\n**进阶：**先延长少量可耐受保持，再增加重复；不通过摄像机自动升级成最大阻力。\n\n**停止或调整条件**\n\n- 异常头痛、眩晕或新上肢麻木无力。\n- 用力时明显不适、屏气或症状持续升高。\n\n**机位与画面：**正面或侧面头肩近景，主要检查明显位移。\n\n**视觉可以观察**\n\n- 头是否明显离开中立、肩耸起、保持计时。\n\n**视觉不能直接判定**\n\n- 真实施力、肌肉收缩、关节压缩或最大力量。\n\n**观察不足时：**用户按开始/结束并自报轻中重用力，明确force_observed=false，不因静止而判未训练。\n\n**动作出处与对应原文：**[REF-S013]；第2页 Neck extension / Isometric neck flexion, lateral flexion, rotation。\n\n**证据性质与适用范围：**医院动作说明。运动形式有公开出处；本卡的减负荷、扶持、候选剂量及视频规则属于实施版本，不能据此声明完整方案已验证疗效。\n\n**依据：**[REF-S013]；背景及临床边界：[AXU-S02]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
    "version": "2026-10-13-full",
    "region": "颈部",
    "level": "L1",
    "equipment": "- 自己的手掌；无需弹力带",
    "objective": "在头部大致不动时练习可耐受的颈部用力与耐力。",
    "startConditions": "- 颈部等长已获当前计划允许，无急性未评估创伤。\n- 用户理解只需轻抵，不是最大用力测试。",
    "stopConditions": "- 异常头痛、眩晕或新上肢麻木无力。\n- 用力时明显不适、屏气或症状持续升高。",
    "sourceDose": "首轮每个选定方向2次×3秒；候选模板每方向3–5次×5秒、次间休息10–20秒；方向与力度由计划确认。",
