    "id": "T-AXU-029",
    "name": "推撑阶梯：墙面→固定台面→地面俯卧撑",
    "kind": "training",
    "complete": true,
    "content": "**区域：**肩/肘/腕/躯干　 **等级：**L1—L2（依支撑高度与任务版本）\n\n**目标：**按支撑高度渐进恢复上肢推力与全身控制。\n\n**器材**\n\n- 坚实墙面或固定台面\n- 地面垫；可选稳定握把\n\n**开始条件**\n\n- 所选版本的肩肘腕和足部承重可耐受；支撑面不滑不动。\n- 手腕伸展受限者的握把须稳定且获准，不临时用易滚哑铃。\n- 地面版本须单独确认肩腕及前足支撑许可；墙面版本完成良好不自动表示可进入地面版本。\n\n**准备与起始位：**从高支撑面开始，双手位置舒适、略宽于肩；脚踩稳，躯干保持可控整体线。\n\n**操作步骤**\n\n1. 先直臂支撑试耐受，确认腕肩和下肢没有明显不适。\n2. 吸气屈肘让身体整体靠近支撑面，肘走舒适斜向路线。\n3. 呼气推回，肘接近伸直但不猛锁，肩胛允许自然移动。\n4. 当前高度稳定且反应合适后，另一次训练才逐级降低支撑面。\n\n**关键要领**\n\n- 头、胸、骨盆大致一起移动，不先探头。\n- 手掌/握把稳定，肩不耸起。\n- 下降和推回都可控，不在底部弹起。\n\n**常见错误**\n\n- 台面晃动、脚滑还继续。\n- 降低高度同时大量加次数，导致腰塌或手腕疼痛。\n\n**试做与候选剂量／评估协议：**首轮当前高度3–5次；候选模板2–3组×6–12次、组间60–90秒。支撑高度、幅度和剂量由计划确认。\n\n**退阶：**提高支撑面、减小幅度；必要时只做短时轻支撑。\n\n**进阶：**墙→高固定台→低台→合适地面版本；稳定后才增加次数或外载，不能只因RPE低而跳级。\n\n高位交替抬手见 T-AXU-045，Push-up Plus见 T-AXU-053；二者改变任务阶段或单侧支撑，不和普通俯卧撑混计。\n\n**停止或调整条件**\n\n- 肩不稳、肘打软、腕锐痛或新麻木。\n- 脚滑、支撑面移动或无法控制下降。\n\n**机位与画面：**侧面全身，正面可补观察明显左右差异；不要求两视角才能完成。\n\n**视觉可以观察**\n\n- 次数、肘屈伸、整体线和节奏、明显侧偏。\n\n**视觉不能直接判定**\n\n- 双手实际受力、胸肩肌激活或组织耐受极限。\n\n**观察不足时：**局部遮挡仅停对应评分；自报次数和版本仍可保存，不清空整组。\n\n**动作出处与对应原文：**[REF-S001] [REF-S027] [REF-S087]；Wall press-up / Push-up：墙面至地面；高台为减负荷登记变式。\n\n**证据性质与适用范围：**公共卫生机构动作说明、大学医疗中心公开示范目录、专业机构训练技术说明。运动形式有公开出处；本卡的减负荷、扶持、候选剂量及视频规则属于实施版本，不能据此声明完整方案已验证疗效。\n\n**依据：**[REF-S001] [REF-S027] [REF-S087]；背景及临床边界：[AXU-S03]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
    "version": "2026-10-13-full",
    "region": "肩/肘/腕/躯干",
    "level": "L1—L2（依支撑高度与任务版本）",
