    "objective": "按支撑高度渐进恢复上肢推力与全身控制。",
    "startConditions": "- 所选版本的肩肘腕和足部承重可耐受；支撑面不滑不动。\n- 手腕伸展受限者的握把须稳定且获准，不临时用易滚哑铃。\n- 地面版本须单独确认肩腕及前足支撑许可；墙面版本完成良好不自动表示可进入地面版本。",
    "stopConditions": "- 肩不稳、肘打软、腕锐痛或新麻木。\n- 脚滑、支撑面移动或无法控制下降。",
