    "region": "胸、肩与上肢水平内收",
    "level": "L2",
    "equipment": "两个略高于肩的可靠绳索锚点，或同方向弹力带锚点；轻阻力。",
    "objective": "练习站姿水平内收与受控回程；不同于卧姿飞鸟。",
    "startConditions": "肩水平展开和内收负荷已获准、锚点可靠；能独立站稳、松开张力并放下握把。",
    "stopConditions": "肩胸锐痛、手麻、锚点松动或无法控制回程。 同时遵守第4节与第12节。",
    "sourceDose": "首轮3次；候选1–2组×6–10次，组间60–90秒。 所有数值为项目候选模板，不是原资料统一处方或进阶阈值。",
