    "id": "T-AXU-035",
    "name": "前臂支撑的负重腕背伸",
    "kind": "training",
    "complete": true,
    "content": "**区域：**腕/前臂伸肌　 **等级：**L1\n\n**目标：**逐步练习腕伸肌的负荷和回程控制。\n\n**器材**\n\n- 桌面\n- 轻小哑铃/小水瓶；或空手\n\n**开始条件**\n\n- 腕背伸抗阻在当前许可内；急性未评估创伤或腕骨痛先处理。\n\n**准备与起始位：**掌心向下，前臂稳定放桌面，腕伸出桌边；手握轻物，肘角记入版本。\n\n**操作步骤**\n\n1. 先空手上下活动，找舒适范围。\n2. 呼气把手背缓慢抬起，前臂不离桌。\n3. 停短暂后控制放低，避免重量把腕猛拉到底。\n4. 如果计划指定辅助上抬/主动下降，明确使用另一手助力并单独记录版本。\n\n**关键要领**\n\n- 动作主要发生在腕，不抬整条前臂。\n- 握持不必用尽全力，但物体不能滑。\n- 回程平稳，手指不做额外猛抓动作。\n\n**常见错误**\n\n- 负荷过大导致前臂抬起或握持绷紧。\n- 把所有肘外侧痛一律当适合高量离心。\n\n**试做与候选剂量／评估协议：**首轮空手或轻物5次；候选模板1–3组×8–15次、组间45–60秒。动作形式、负荷和疼痛反应须按个体计划。\n\n腕背伸等长与辅助上抬/主动缓降分别启用hold和eccentric协议（见习47）。固定重量、前臂支撑、腕起点；候选先短时轻等长试做，再按计划增加保持，不能仅凭计时确认发力。\n\n**退阶：**空手、小范围或获准轻等长；不能因看不到收缩就要求加力。\n\n**进阶：**先提高可耐受控制和重复，再小幅加重；改变肘角是另一个负荷变量。\n\n**停止或调整条件**\n\n- 腕背锐痛、明显肘痛上升、新麻木。\n- 握持不稳或无法控制下降。\n\n**机位与画面：**腕侧面近景，Hand与Body采用统一图像坐标。\n\n**视觉可以观察**\n\n- 腕投影活动、次数、前臂明显离桌和节奏。\n\n**视觉不能直接判定**\n\n- 肌腱应力、实际握力和Hand/Body未配准world的真实角。\n\n**观察不足时：**握物遮住Hand时只按节奏与自报完成，不要求拿开重量重复整组。\n\n**动作出处与对应原文：**[REF-S017] [REF-S089]；Wrist extension / AAOS Exercises Page2：负重背伸及助上抬、主动缓降；保持时长另定。\n\n**证据性质与适用范围：**医院动作说明、专业学会患者训练手册。运动形式有公开出处；本卡的减负荷、扶持、候选剂量及视频规则属于实施版本，不能据此声明完整方案已验证疗效。\n\n**依据：**[REF-S017] [REF-S089]；背景及临床边界：[AXU-S05] [AXU-S08] [AXU-S11]。动作形式、背景指南和产品测量证据按第8节分别解释。\n\n**设计与见习追溯：**[AXU-S12]；本库单人设置、阶段规则与候选量用于实施登记，见习经历和项目设计不属于临床疗效证据。",
    "version": "2026-10-13-full",
