    "level": "L1",
    "equipment": "- 桌面\n- 轻小哑铃/小水瓶；或空手",
    "objective": "逐步练习腕伸肌的负荷和回程控制。",
    "startConditions": "- 腕背伸抗阻在当前许可内；急性未评估创伤或腕骨痛先处理。",
    "stopConditions": "- 腕背锐痛、明显肘痛上升、新麻木。\n- 握持不稳或无法控制下降。",
    "sourceDose": "首轮空手或轻物5次；候选模板1–3组×8–15次、组间45–60秒。动作形式、负荷和疼痛反应须按个体计划。\n\n腕背伸等长与辅助上抬/主动缓降分别启用hold和eccentric协议（见习47）。固定重量、前臂支撑、腕起点；候选先短时轻等长试做，再按计划增加保持，不能仅凭计时确认发力。",
